import csv
path='/root/weoapr2025all.xls'
with open(path, 'r', encoding='utf-16-le') as f:
    reader=csv.reader(f, delimiter='\t')
    header=next(reader)
    idx={name:i for i,name in enumerate(header)}
    data={'NGDP_R':{}, 'NGDP_RPCH':{}}
    for row in reader:
        if len(row)<len(header):
            row=row+['']*(len(header)-len(row))
        if row[idx['Country']]=='Georgia' and row[idx['WEO Subject Code']] in data:
            code=row[idx['WEO Subject Code']]
            for y in range(2000, 2028):
                val=row[idx[str(y)]]
                data[code][y]=float(val) if val not in ('','n/a','…','..') else None
    print('2027', data['NGDP_R'][2027], data['NGDP_RPCH'][2027])
    print('last available NGDP_R years', [y for y,v in data['NGDP_R'].items() if v is not None][-5:])
